import os
import cv2
import numpy as np
from sklearn.model_selection import train_test_split

# --- Configuration ---
DATA_DIR = os.path.join(path, 'Car_Brand_Logos/Train') # Your base directory
IMAGE_SIZE = (128, 128) # Resize images to this size (width, height)
BATCH_SIZE = 32
EPOCHS = 10

# --- 1. Loop all car model and all image name & Collect Data ---
image_paths = []
labels = []

car_models = sorted(os.listdir(DATA_DIR)) # Get a sorted list of car model folders

print(f"Found {len(car_models)} car models.")

for model_name in car_models:
    model_path = os.path.join(DATA_DIR, model_name)
    if os.path.isdir(model_path):
        for image_name in os.listdir(model_path):
            if image_name.endswith(('.jpg', '.jpeg', '.png')): # Filter for image files
                image_full_path = os.path.join(model_path, image_name)
                image_paths.append(image_full_path)
                labels.append(model_name)

print(f"Collected {len(image_paths)} images.")

# --- 2. Load and Preprocess Images ---
# Initialize empty list for processed images
images = []

for i, img_path in enumerate(image_paths):
    img = cv2.imread(img_path)
    if img is not None:
        img = cv2.resize(img, IMAGE_SIZE) # Resize image
        img = img / 255.0 # Normalize pixel values to [0, 1]
        images.append(img)
    else:
        print(f"Warning: Could not read image {img_path}. Skipping.")

    # Optional: Print progress
    if (i + 1) % 100 == 0:
        print(f"Processed {i + 1}/{len(image_paths)} images...")

images = np.array(images) # Convert list of images to a NumPy array

# --- 3. Create Labels (Encoding) ---
