print("Images array shape:", images.shape)
print("Labels array shape:", one_hot_labels.shape)
print("Number of unique car models:", len(car_models))
print("Car models and their encoded values:", list(label_encoder.classes_))

"""**Train Test Split**"""

# --- 4. Split Data into Training and Validation Sets ---
X_train, X_val, y_train, y_val = train_test_split(
    images, one_hot_labels, test_size=0.2, random_state=42, stratify=one_hot_labels
)


print(f"Training images shape: {X_train.shape}")
print(f"Validation images shape: {X_val.shape}")
print(f"Training labels shape: {y_train.shape}")
print(f"Validation labels shape: {y_val.shape}")

