import os
import numpy as np
import keras
from keras import layers
from tensorflow import data as tf_data
import matplotlib.pyplot as plt

# Your model definition remains almost identical
input_shape = (IMAGE_SIZE[0], IMAGE_SIZE[1], 3)
print(car_models)
num_classes = len(car_models) # Ensure 'labels' is defined

model = keras.Sequential([
    # Add layers here
    layers.Conv2D(32, (3, 3), activation='relu', input_shape=input_shape),

])

# The compilation step might slightly vary depending on the backend's native optimizers/losses if you go beyond Keras's built-in ones.
# But generally, Keras's optimizers and losses are backend-agnostic.
model.compile(optimizer='adam', loss='categorical_crossentropy', metrics=['accuracy'])
model.summary()

# keras.utils.plot_model(model, show_shapes=True)

"""**Train Model**"""

# Convert labels to numerical representation using LabelEncoder
print("\n--- Training the CNN Model ---")
history = model.fit(
    X_train, y_train,
    epochs=EPOCHS,
    batch_size=BATCH_SIZE,
    validation_data=(X_val, y_val)
)

print("\n--- Model Training Complete ---")

# Optional: Evaluate the model on the validation set
loss, accuracy = model.evaluate(X_val, y_val, verbose=0)
print(f"Validation Loss: {loss:.4f}")
print(f"Validation Accuracy: {accuracy:.4f}")

